const raw = $input.first().json;
const rows = Array.isArray(raw) ? raw : (raw && raw.client_id ? [raw] : []);
const seen = {};
const clients = [];
for (const r of rows) { if (r.client_id && !seen[r.client_id]) { seen[r.client_id] = true; clients.push({ client_id: r.client_id }); } }
if (clients.length === 0) return [{ json: { _empty: true } }];
return clients.map(function (c) { return { json: c }; });

const allOf = function (name) {
  try {
    const items = $(name).all().map(function (i) { return i.json; });
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    return items;
  } catch (e) { return []; }
};
const schedules = allOf('Fetch Schedule');
const personalities = allOf('Fetch Personality');
const triggers = allOf('Fetch Pending Triggers');
const clientId = $('Per Client').item.json.client_id;

// Defaults if rows missing
const schedule = schedules[0] || { quiet_hours_start: '21:00', quiet_hours_end: '08:00', timezone: 'America/Toronto', max_actions_per_day: 100, max_actions_per_lead_per_week: 3, weekend_active: false };
const personality = personalities[0] || { voice_tone: 'professional', formality_level: 'business_casual', vertical_context: 'service_industry', escalation_rules: {} };

// Quiet hours check (server-side approximation in client TZ).
// Heuristic: convert now → client tz hour using Intl, compare to quiet_hours.
let quiet = false;
try {
  const tzHour = parseInt(new Intl.DateTimeFormat('en-CA', { timeZone: schedule.timezone || 'America/Toronto', hour: 'numeric', hour12: false }).format(new Date()), 10);
  const startH = parseInt(String(schedule.quiet_hours_start || '21:00').split(':')[0], 10);
  const endH = parseInt(String(schedule.quiet_hours_end || '08:00').split(':')[0], 10);
  if (startH > endH) {
    // wraps midnight
    quiet = (tzHour >= startH || tzHour < endH);
  } else {
    quiet = (tzHour >= startH && tzHour < endH);
  }
} catch (e) { /* ignore tz errors */ }

if (quiet) return [{ json: { _quiet: true, client_id: clientId } }];
if (triggers.length === 0) return [{ json: { _empty: true, client_id: clientId } }];

// Fan out one item per trigger; carry schedule/personality
return triggers.map(function (t) { return { json: { trigger: t, client_id: clientId, schedule: schedule, personality: personality } }; });

// Build Claude prompt for action decision per trigger.
const t = $json.trigger;
const p = $json.personality;
const clientId = $json.client_id;

const systemPrompt = [
  'You are the Crystallux AI Sales Agent decision-maker for client_id=' + clientId + '.',
  'Vertical context: ' + (p.vertical_context || 'service_industry'),
  'Tone: ' + (p.voice_tone || 'professional') + ' / ' + (p.formality_level || 'business_casual'),
  '',
  'You receive ONE pending behavioral trigger and decide ONE action. Output strictly JSON.',
  '',
  'Schema: {',
  '  "action_type": "send_email" | "send_sms" | "send_whatsapp" | "send_video" | "phone_call" | "wait" | "escalate",',
  '  "channel":     "email" | "sms" | "whatsapp" | "voice" | null,',
  '  "reasoning":   "<1-2 sentences>",',
  '  "message":     "<the actual message text if sending>",',
  '  "confidence":  <0..1>',
  '}',
  '',
  'Rules:',
  '- Use the trigger\'s recommended_action UNLESS you have strong reason to override.',
  '- For high composite_score (80+): act. For 50-79: act if channel low-cost (email). For <50: prefer wait.',
  '- Use personality.escalation_rules to decide if you should escalate to human (output action_type="escalate").',
  '- Match tone of personality. Use the trigger\'s generated_message as the starting point — refine for tone.',
  '- Never include URLs you do not have. Never invent facts.'
].join('\n');

const userPrompt = JSON.stringify({
  trigger: {
    archetype_id: t.archetype_id,
    composite_score: t.composite_score,
    recommended_action: t.recommended_action,
    suggested_message: t.generated_message
  },
  lead_context: t.context || {},
  // What the agent went and looked up, and what came back. A tool that
  // failed is reported as an error, never as a finding about the lead.
  capability_used: $json.tool_used || null,
  capability_reason: $json.tool_reason || null,
  capability_result: $json.tool_result || null,
  capability_error: $json.tool_error || null,
  escalation_rules: p.escalation_rules || {}
});

return { json: {
  trigger_id: t.id,
  lead_id: t.lead_id,
  client_id: clientId,
  correlation_id: t.correlation_id || $json.correlation_id || null,
  tool_used: $json.tool_used || null,
  tool_error: $json.tool_error || null,
  proof_run: $json._proof_run || false,
  claude_payload: {
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 600,
    temperature: 0.3,
    system: systemPrompt,
    messages: [ { role: 'user', content: userPrompt } ]
  }
} };

const ctx = $('Build Claude Prompt').item.json;
const resp = $input.item.json || {};

// A model call that failed is not a decision to wait. The previous version
// turned any unusable response into a persisted row saying action_type
// 'wait', reasoning 'parse_failed', confidence 0 -- indistinguishable, once
// stored, from the agent genuinely deciding to hold off. Same rule as
// scoring: on model or parser failure, record the failure and persist
// nothing.

const httpErr = resp.error || resp.__error || null;
let textOut = '';
try { textOut = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) {}

let decision = null;
if (textOut) {
  try { decision = JSON.parse(String(textOut).replace(/```json|```/g, '').trim()); } catch (e) {}
}

if (!decision) {
  const reason = httpErr
    ? ('model_call_failed: ' + JSON.stringify(httpErr).slice(0, 300))
    : (textOut ? 'model_response_unparseable' : 'model_returned_no_content');
  return { json: {
    _decision_error: true,
    error_reason: reason,
    trigger_id: ctx.trigger_id,
    lead_id: ctx.lead_id,
    client_id: ctx.client_id,
    correlation_id: ctx.correlation_id || null
  } };
}

const tokens = (resp.usage && (resp.usage.input_tokens + resp.usage.output_tokens)) || 0;
return { json: {
  _decision_error: false,
  trigger_id: ctx.trigger_id,
  lead_id: ctx.lead_id,
  client_id: ctx.client_id,
  decision_row: {
    client_id: ctx.client_id,
    lead_id: ctx.lead_id,
    decision_type: decision.action_type || 'wait',
    reasoning: decision.reasoning || null,
    context_used: { trigger_id: ctx.trigger_id, channel: decision.channel,
                    generated_message: decision.message,
                    correlation_id: ctx.correlation_id || null,
                    capability_used: ctx.tool_used || null,
                    capability_error: ctx.tool_error || null,
                    proof_run: ctx.proof_run || false },
    target_role: null,
    confidence_score: Math.min(Math.max(parseFloat(decision.confidence) || 0, 0), 1),
    outcome: 'pending'
  },
  message: decision.message || '',
  channel: decision.channel || null,
  action_type: decision.action_type || 'wait',
  tokens: tokens
} };

// Controlled proof entry. Not an autonomous path.
//
// The decision engine had only a schedule trigger, named "(DEACTIVATED)",
// and no webhook -- so there was no way to invoke it at all. That, plus
// zero pending behavioral_triggers, is why agent_decisions has been 0
// since the runtime was built: no entry, and no input.
//
// This entry supplies ONE synthetic trigger inline for a named lead. It
// deliberately does NOT write to behavioral_triggers, so no autonomous
// trigger machinery is enabled, and it bypasses quiet hours because an
// explicit operator-initiated test is not an unsolicited 1am contact --
// nothing is sent either way; the policy gate decides that downstream.

const body = ($input.item.json && $input.item.json.body) || $input.item.json || {};
const secret = body.internal_secret || '';
const expected = $env.INTERNAL_EMAIL_SECRET || '';

// Two different failures, told apart. An opaque 401 cannot distinguish
// "you sent the wrong secret" from "this server has no secret configured,
// so nobody can ever authenticate" -- and 60 workflows depend on this one
// variable. Reporting the unconfigured case discloses nothing usable: when
// it is unset, fail-closed means no caller gets in either way, so this
// leaks a configuration state, never a credential.
if (!expected) {
  return { json: { _reject: true, status: 503,
    error: 'internal_secret_not_configured',
    hint: 'INTERNAL_EMAIL_SECRET is not set in the n8n container environment. No caller can authenticate until it is.' } };
}
if (secret !== expected) {
  return { json: { _reject: true, status: 401, error: 'internal secret required' } };
}
if (!body.client_id) {
  return { json: { _reject: true, status: 400, error: 'client_id required' } };
}

// Preflight the container configuration the run depends on, after the
// caller is authenticated. Reported here rather than discovered halfway
// through: the model call sits behind an early 202, so a missing key
// used to surface as silence rather than as an error.
const missing = [];
if (!$env.ANTHROPIC_API_KEY) missing.push('ANTHROPIC_API_KEY');
if (missing.length) {
  return { json: { _reject: true, status: 503,
    error: 'runtime_not_configured', missing: missing,
    hint: 'The decision engine cannot reach the model without this variable set in the n8n container.' } };
}

const correlation = body.correlation_id || ('proof-' + Date.now());

return { json: {
  _reject: false,
  _proof_run: true,
  client_id: body.client_id,
  lead_id: body.lead_id || null,
  correlation_id: correlation,
  recommended_action: body.recommended_action || 'send_email',
  trigger: {
    id: null,
    client_id: body.client_id,
    lead_id: body.lead_id || null,
    trigger_type: body.trigger_type || 'manual_review_request',
    status: 'pending',
    context: body.context || 'Operator-initiated read-only proof run.',
    _synthetic: true,
    correlation_id: correlation
  }
} };

// Proof run: use the supplied synthetic trigger, skip quiet hours.
//
// The trigger is now built from a REAL tenant lead so the model has
// something to reason about. The first proof run passed nulls for every
// field Build Claude Prompt serialises, and the model correctly refused to
// invent a recommendation -- honest, but it meant no capability was ever
// selected and the policy gate was never asked to refuse anything.
//
// Nothing here is fabricated. composite_score is the lead's own score;
// the signal and research come from its columns. recommended_action
// defaults to send_email precisely so that recommend_only has to refuse it.

const ctx = $('Validate Proof Request').item.json;

const allOf = function (name) {
  try {
    const items = $(name).all().map(function (i) { return i.json; });
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    return items;
  } catch (e) { return []; }
};

const personalities = allOf('Fetch Personality (Proof)');
const personality = personalities[0] || {
  voice_tone: 'professional', formality_level: 'business_casual',
  vertical_context: 'construction', escalation_rules: {}
};

const leads = allOf('Fetch Proof Lead');
const lead = leads[0] || null;

// A signal that failed to detect is not evidence about the prospect, so it
// is passed to the model as absent rather than as a weak signal.
const ERROR_CONF = ['Unavailable', 'Error', 'Failed'];
const signalUsable = lead && lead.detected_signal &&
  ERROR_CONF.indexOf(lead.signal_confidence) < 0;

const trigger = {
  id: null,
  client_id: ctx.client_id,
  lead_id: lead ? lead.id : null,
  trigger_type: ctx.trigger.trigger_type,
  status: 'pending',
  archetype_id: lead ? (lead.priority_level || 'unclassified') : null,
  composite_score: lead ? lead.lead_score : null,
  recommended_action: ctx.recommended_action || 'send_email',
  generated_message: null,
  context: {
    company: lead ? lead.company : null,
    industry: lead ? lead.industry : null,
    city: lead ? lead.city : null,
    job_title: lead ? lead.job_title : null,
    research_summary: lead ? lead.research_summary : null,
    likely_business_need: lead ? lead.likely_business_need : null,
    detected_signal: signalUsable ? lead.detected_signal : null,
    signal_confidence: signalUsable ? lead.signal_confidence : null,
    signal_state: !lead ? 'no_lead'
                : signalUsable ? 'verified'
                : (lead.detected_signal ? 'detection_failed' : 'none'),
    research_present: !!(lead && lead.research_summary)
  },
  _synthetic: true,
  correlation_id: ctx.correlation_id
};

return [{ json: {
  trigger: trigger,
  client_id: ctx.client_id,
  correlation_id: ctx.correlation_id,
  schedule: { quiet_hours_start: '00:00', quiet_hours_end: '00:00',
              timezone: 'America/Toronto', max_actions_per_day: 1,
              max_actions_per_lead_per_week: 1 },
  personality: personality,
  _proof_run: true
} }];

// Stage 1: does this decision need more information, and if so which
// allowed capability provides it?
//
// The allow-list is the ones the MCP gateway actually implements. The
// personality's auto_allowed also names get_vertical_context, research_lead
// and score_lead, which do not exist as tools -- offering those would only
// invite a choice that must fail.

const t = $json.trigger || {};
const p = $json.personality || {};
const ctx = t.context || {};

const ALLOWED = [
  { name: 'assess_why_now',
    use: 'Classify whether there is a verified, time-sensitive reason to act now.' },
  { name: 'next_best_action',
    use: 'Get the evidence-based recommended action, urgency and risk class for this lead.' },
  { name: 'retrieve_lead_memory',
    use: 'Recall what has previously been learned or agreed with this lead.' }
];

const system = [
  'You are the Crystallux sales agent deciding whether you need more information',
  'before recommending an action for one lead.',
  '',
  'Vertical: ' + (p.vertical_context || 'service_industry'),
  'Autonomy: ' + ((p.escalation_rules || {}).autonomy_level || 'recommend_only'),
  '',
  'Available READ capabilities:',
  ALLOWED.map(function (a) { return '  ' + a.name + ' -- ' + a.use; }).join('\n'),
  '',
  'Reply with STRICT JSON only:',
  '{ "needs_tool": true|false,',
  '  "tool": "<one of the names above, or null>",',
  '  "reason": "<one sentence>",',
  '  "arguments": { "lead_id": "<the lead id, if the tool needs one>" } }',
  '',
  'Rules:',
  '- Choose at most ONE tool. Choose none if the context already answers the question.',
  '- Never name a tool that is not listed above.',
  '- These are read-only. You are NOT deciding to contact anyone at this step.'
].join('\n');

const user = JSON.stringify({
  lead_id: t.lead_id,
  composite_score: t.composite_score,
  archetype: t.archetype_id,
  proposed_action: t.recommended_action,
  known_context: {
    company: ctx.company, industry: ctx.industry, city: ctx.city,
    research_present: ctx.research_present,
    signal_state: ctx.signal_state,
    detected_signal: ctx.detected_signal,
    signal_confidence: ctx.signal_confidence
  }
});

return { json: {
  _carry: $json,
  tool_payload: {
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 400,
    temperature: 0,
    system: system,
    messages: [{ role: 'user', content: user }]
  }
} };

// Stage 1 result, judged fail-closed.
//
// A malformed or unexpected answer means NO tool call -- never a guess and
// never a business decision. Same rule the scorer and signal classifier
// follow: a parse failure is recorded as a failure, not smoothed into data.

const carry = $('Build Tool Prompt').item.json._carry;
const resp = $input.item.json || {};

const ALLOWED = ['assess_why_now', 'next_best_action', 'retrieve_lead_memory'];

let text = '';
try { text = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) {}

let choice = null;
if (text) {
  try { choice = JSON.parse(String(text).replace(/```json|```/g, '').trim()); } catch (e) {}
}

const out = {
  _carry: carry,
  needs_tool: false,
  tool: null,
  tool_reason: null,
  tool_arguments: {},
  selection_error: null
};

if (!choice) {
  out.selection_error = text ? 'tool_choice_unparseable' : 'tool_selection_no_content';
  return { json: out };
}

if (choice.needs_tool !== true) {
  out.tool_reason = choice.reason || 'model judged existing context sufficient';
  return { json: out };
}

if (!choice.tool || ALLOWED.indexOf(choice.tool) < 0) {
  out.selection_error = 'tool_not_allowed:' + String(choice.tool);
  return { json: out };
}

// Tenant context is mandatory, and arguments are rebuilt rather than
// trusted: only the lead this run is actually about may be passed on.
if (!carry.client_id) {
  out.selection_error = 'missing_tenant_context';
  return { json: out };
}

const leadId = (carry.trigger && carry.trigger.lead_id) || null;
const wants = (choice.arguments && choice.arguments.lead_id) || null;
if (wants && leadId && String(wants) !== String(leadId)) {
  out.selection_error = 'lead_mismatch_refused';
  return { json: out };
}
if (!leadId) {
  out.selection_error = 'no_lead_for_tool';
  return { json: out };
}

out.needs_tool = true;
out.tool = choice.tool;
out.tool_reason = choice.reason || null;
out.tool_arguments = { lead_id: leadId };
return { json: out };

// Fold the tool result (if any) back into the shape Build Claude Prompt
// already expects, so the existing decision stage is unchanged apart from
// having more to reason with.

const sel = $('Parse Tool Choice').item.json;
const carry = sel._carry;

const allOf = function (name) {
  try {
    const items = $(name).all().map(function (i) { return i.json; });
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    return items;
  } catch (e) { return []; }
};

let toolResult = null;
let toolError = null;

if (sel.needs_tool) {
  const raw = allOf('Call MCP Agent Tools')[0] || null;
  if (!raw) {
    toolError = 'mcp_no_response';
  } else if (raw.success === false) {
    // A refused or failed capability is reported as such. It must not
    // reappear as if it were a finding about the lead.
    toolError = 'mcp_refused:' + (raw.error || 'unknown');
  } else {
    toolResult = raw.data !== undefined ? raw.data : raw;
  }
}

return { json: Object.assign({}, carry, {
  tool_used: sel.needs_tool ? sel.tool : null,
  tool_reason: sel.tool_reason || null,
  tool_result: toolResult,
  tool_error: toolError || sel.selection_error || null
}) };
